const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define Monte Pisano, Italy (center coordinates)
  const montePisano = ee.Geometry.Point([10.4, 43.7]);
  const region = ee.Geometry.Buffer(montePisano, 5000); // 5 km buffer

  // 2. Query Landsat 8 L2 for Feb 25, 2019
  const col = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
    .filterBounds(region)
    .filterDate('2019-02-25', '2019-02-26');

  const size = col.size().getInfo();
  console.log(`Images found on Feb 25, 2019: ${size}`);

  if (size === 0) {
    console.log('No Landsat 8 images available for this date.');
    console.log('C1');
    return;
  }

  // 3. Get the first image
  const img = ee.Image(col.first());
  const dateStr = ee.Date(img.get('system:time_start')).format('YYYY-MM-dd HH:mm').getInfo();
  console.log(`Image date/time: ${dateStr}`);

  // 4. Extract thermal band (Band 10, temperature)
  // Scale reflectance bands (SR_B2, SR_B3, SR_B4, SR_B5 are already in reflectance)
  const thermal = img.select('ST_B10'); // Thermal band
  const red = img.select('SR_B4');
  const green = img.select('SR_B3');
  const blue = img.select('SR_B2');
  const nir = img.select('SR_B5');

  // 5. Calculate NDVI to identify vegetation/fire contrast
  const ndvi = nir.subtract(red).divide(nir.add(red));

  // 6. Calculate NBR (Normalized Burn Ratio) to detect fire
  const swir = img.select('SR_B7'); // SWIR band
  const nbr = nir.subtract(swir).divide(nir.add(swir));

  // 7. Count valid pixels in region
  const validPixels = img.select('SR_B4').reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: region,
    scale: 30,
    maxPixels: 1e9
  }).getInfo();

  const pixelCount = validPixels['SR_B4'] || 0;
  console.log(`Valid pixels in region: ${pixelCount}`);

  if (pixelCount === 0) {
    console.log('No valid pixels after processing.');
    console.log('C2');
    return;
  }

  // 8. Analyze smoke/fire signature along east-west transect
  // Create east and west sampling points
  const eastPoint = ee.Geometry.Point([10.5, 43.7]);  // East
  const westPoint = ee.Geometry.Point([10.3, 43.7]);  // West
  const northPoint = ee.Geometry.Point([10.4, 43.8]); // North
  const southPoint = ee.Geometry.Point([10.4, 43.6]); // South

  // Sample NBR (fire detection) at these points
  const nbrEast = nbr.sample(eastPoint, 30).first().get('SR_B5').getInfo();
  const nbrWest = nbr.sample(westPoint, 30).first().get('SR_B5').getInfo();
  const nbrNorth = nbr.sample(northPoint, 30).first().get('SR_B5').getInfo();
  const nbrSouth = nbr.sample(southPoint, 30).first().get('SR_B5').getInfo();

  console.log(`NBR East: ${nbrEast !== null ? nbrEast.toFixed(3) : 'N/A'}`);
  console.log(`NBR West: ${nbrWest !== null ? nbrWest.toFixed(3) : 'N/A'}`);
  console.log(`NBR North: ${nbrNorth !== null ? nbrNorth.toFixed(3) : 'N/A'}`);
  console.log(`NBR South: ${nbrSouth !== null ? nbrSouth.toFixed(3) : 'N/A'}`);

  // 9. Analyze thermal signature (higher temp = fire/smoke)
  const thermalEast = thermal.sample(eastPoint, 30).first().get('ST_B10').getInfo();
  const thermalWest = thermal.sample(westPoint, 30).first().get('ST_B10').getInfo();

  console.log(`Thermal (K) East: ${thermalEast !== null ? thermalEast.toFixed(1) : 'N/A'}`);
  console.log(`Thermal (K) West: ${thermalWest !== null ? thermalWest.toFixed(1) : 'N/A'}`);

  // 10. Determine smoke direction
  // Higher NBR to the east = fire/burn signature moved east = plume moving east
  let smokeMovementEast = false;
  let confidence = 0;

  if (nbrEast !== null && nbrWest !== null) {
    const nbrDiff = nbrEast - nbrWest;
    console.log(`NBR East-West difference: ${nbrDiff.toFixed(4)}`);
    if (nbrDiff > 0.05) {
      smokeMovementEast = true;
      confidence = 1;
    } else if (nbrDiff < -0.05) {
      smokeMovementEast = false;
      confidence = 1;
    } else {
      // Inconclusive from NBR alone
      confidence = 0.5;
    }
  }

  if (thermalEast !== null && thermalWest !== null) {
    const thermalDiff = thermalEast - thermalWest;
    console.log(`Thermal East-West diff (K): ${thermalDiff.toFixed(1)}`);
    if (thermalDiff > 50) {
      smokeMovementEast = true;
      confidence = 1;
    }
  }

  console.log(`Smoke plume moving east (confidence: ${confidence}): ${smokeMovementEast}`);

  if (confidence === 0.5) {
    console.log('Inconclusive directional data from single timestep.');
    console.log('C3');
  } else if (smokeMovementEast) {
    console.log('A');
  } else {
    console.log('B');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
